        while (sb.length() > k) {
            StringBuilder next = new StringBuilder();
            for (int i = 0; i < sb.length(); i += k) {
                int sum = 0;
                for (int j = i; j < Math.min(i + k, sb.length()); j++) {
                    sum += sb.charAt(j) - '0';
