class Solution {
public:
    string digitSum(string s, int k) {
        vector<int> d;
        for (char c : s) d.push_back(c - '0');
        while ((int)d.size() > k) {
            vector<int> nd;
            for (int i = 0; i < (int)d.size(); i += k) {
                int sum = 0;
                for (int j = i; j < min(i + k, (int)d.size()); j++) sum += d[j];
                string t = to_string(sum);
                for (char c : t) nd.push_back(c - '0');
            }
            d = nd;
        }
        string res;
        for (int x : d) res += char('0' + x);
        return res;
    }
};

