class Solution {
    public String digitSum(String s, int k) {
        List<Integer> d = new ArrayList<>();
        for (char c : s.toCharArray()) d.add(c - '0');
        while (d.size() > k) {
            List<Integer> nd = new ArrayList<>();
            for (int i = 0; i < d.size(); i += k) {
                int sum = 0;
                for (int j = i; j < Math.min(i + k, d.size()); j++) sum += d.get(j);
                for (char c : String.valueOf(sum).toCharArray()) nd.add(c - '0');
            }
            d = nd;
        }
        StringBuilder sb = new StringBuilder();
        for (int x : d) sb.append(x);
        return sb.toString();
    }
}

