var digitSum = function(s, k) {
    let d = [...s].map(Number);
    while (d.length > k) {
        const nd = [];
        for (let i = 0; i < d.length; i += k) {
            const sum = d.slice(i, i + k).reduce((a, b) => a + b, 0);
            nd.push(...String(sum).split("").map(Number));
        }
        d = nd;
    }
    return d.join("");
};
